                product_category_ids?: string[];
                /** @description Restrict the results to inventory of products in any of these product groups, each identified by its Distru product group id. Multiple ids are OR-ed. Omit to include every group; ids that do not belong to the company match nothing. At most 200 ids. */
                product_group_ids?: string[];
