                product_skus?: string[];
                /** @description Restrict the results to inventory of products with any of these strains, each identified by its Distru strain id. Multiple ids are OR-ed. Omit to include every strain; ids that do not belong to the company match nothing. At most 200 ids. */
                product_strain_ids?: string[];
