    "DistruPublic.V1.MetrcController.list_transfers": {
        parameters: {
            query?: {
                /**
                 * @description Filter by the transfer's direction relative to the owning license: `INCOMING` (shipped to it) or `OUTGOING` (shipped from it). Omit to return both.
                 * @example INCOMING
                 */
                direction?: "INCOMING" | "OUTGOING";
                /**
                 * @description Filter by when Distru last fetched the transfer from Metrc (the `fetched_datetime` in the response). Accepts a comma-separated `from,to` range (ISO-8601 UTC); either side may be omitted, e.g. `,2022-07-10T00:00:00Z` returns transfers last fetched on or before that time.
                 * @example ,2022-07-10T00:00:00Z
                 */
                fetched_datetime?: string;
                /** @description Filter to transfers with these Metrc transfer identifiers — Metrc's own integer IDs (the `id` in the response), not Distru IDs. Matches a transfer if its Metrc ID equals any of the listed values (OR semantics). An empty list is ignored. At most 200 IDs may be given. */
                ids?: number[];
                /**
                 * @description Filter by the transfer's `import_status`:
                 *     • `IMPORTED` — imported into Distru as a sales order (outgoing), a purchase (incoming), or a stock transfer
                 *     • `IGNORED` — not imported and marked ignore-for-import in Distru
                 *     • `UNIMPORTED` — neither imported nor ignored, whether or not it is importable
                 *     Omit to return every status. Combine `UNIMPORTED` with `is_importable=true` to keep only the transfers that can be imported now.
                 * @example UNIMPORTED
                 */
                import_status?: "IGNORED" | "IMPORTED" | "UNIMPORTED";
                /** @description When `true`, keep only transfers that can currently be imported into Distru: flagged importable by Metrc's package states, not yet imported, and not marked ignore-for-import in Distru. `false` and omitted behave the same (no filter). */
                is_importable?: boolean;
                /**
                 * @description Filter to transfers belonging to this license, given as a Distru license resource ID (as returned by the licenses endpoint — not a Metrc or state license number). Omit to return transfers across all of the company's licenses; a license ID that doesn't belong to your company simply returns no transfers.
                 * @example b1f4c2a0-9c3e-4d2b-8f1a-2e5c6d7a8b9c
                 */
                license_id?: string;
                /**
                 * @description Filter to transfers belonging to the Metrc license with this license number (exact match, not a substring). A convenience alternative to `license_id`; combining the two is a 400. Unlike `license_id`, an unknown value is rejected — if your company has no Metrc license with this number the request fails with a 400.
                 * @example ?license_number=C11-0000001-LIC
                 */
                license_number?: string;
                /**
                 * @description Filter to the single transfer whose manifest number equals this value exactly. Use `search` for substring matching.
                 * @example 0000012345
                 */
                manifest_number?: string;
                /** @description Filter to transfers carrying the package with this Metrc package identifier — Metrc's own integer id, the same `id` returned by [GET /public/v1/metrc/packages](#get-metrc-packages) and by each delivery package in the response. */
                metrc_package_id?: number;
                /**
                 * @description Filter to transfers carrying the package with this full 24-character Metrc tag label (case-sensitive exact match).
                 * @example 1A4FF0100000022000004999
                 */
                package_label?: string;
                /**
                 * @description Page selector. Page size is fixed by the server; paginate by following the `next_page` URL in each response rather than building page selectors yourself — it is null on the last page. `next_page` uses `page[after]=<cursor>`, an opaque token marking where the next page resumes; pass it back exactly as given, and only to the endpoint that issued it. This is seek-based, so every page stays fast no matter how deep you page.
                 * @example ?page[after]=cursor
                 */
                page?: string;
                /**
                 * @description Filter to transfers whose manifest number contains this value (case-insensitive substring match). Must be at least 4 characters; a shorter value is a 400.
                 * @example 1234
                 */
                search?: string;
                /**
                 * @description Filter to transfers whose shipper license number or any delivery's recipient license number contains this value (case-insensitive substring match). Must be at least 4 characters; a shorter value is a 400. Unlike `license_number`, which picks the license a transfer belongs to, this matches the facilities on the manifest.
                 * @example ?search_license_number=C11-0000
                 */
                search_license_number?: string;
            };
            header?: never;
            path?: never;
            cookie?: never;
        };
        requestBody?: never;
        responses: {
            /** @description A list of Metrc transfers */
            200: {
                headers: {
                    [name: string]: unknown;
                };
                content: {
                    "*/*": components["schemas"]["MetrcTransfers"];
                };
            };
            /** @description Invalid parameters */
            400: {
                headers: {
                    [name: string]: unknown;
                };
                content: {
                    "*/*": components["schemas"]["ErrorResponse"];
                };
            };
            /** @description Missing or invalid API token */
            401: {
                headers: {
                    [name: string]: unknown;
                };
                content: {
                    "*/*": components["schemas"]["ErrorResponse"];
                };
            };
            /** @description The API token lacks the required permission */
            403: {
                headers: {
                    [name: string]: unknown;
                };
                content: {
                    "*/*": components["schemas"]["ErrorResponse"];
                };
            };
        };
    };
